#!/usr/bin/env python3
"""Write evidence-bound M3 result and bilingual supplement documents."""
import csv,json
from pathlib import Path
REPO=Path(__file__).resolve().parents[1];ROOT=REPO/"reports/nns_vit_endpoint_m3_r1_20260919";PAPER=REPO/"papers/nns_vit_endpoint"
sys_path=str(REPO/"src")
import sys
sys.path.insert(0,sys_path)
from vitnns.endpoint_m3_statistics import bootstrap_median
def csvrows(name):
 with (ROOT/name).open() as f:return list(csv.DictReader(f))
def fmt(x):return "NA" if x in (None,"") else f"{float(x):.4f}"
def p_fmt(x):return "NA" if x in (None,"") else f"{float(x):.3e}"
def main():
 tests=json.loads((ROOT/"atlas_tests.json").read_text())["tests"];summary=csvrows("atlas_summary.csv");validation=json.loads((ROOT/"task_validation.json").read_text());fid=json.loads((ROOT/"m3a_fidelity.json").read_text());op=json.loads((ROOT/"m3a_operator_validation.json").read_text())
 test_table="\n".join(f"| {t['model']} | {t['contrast']} | {fmt(t['median_difference'])} | {t['positive']}/{t['negative']}/{t['ties']} | {p_fmt(t['holm_p'])} | {'SUPPORTED' if t['reject'] else 'NOT_SUPPORTED'} |" for t in tests);depth=[]
 for model in ("vit_b16","deit_s16"):
  for metric in ("entropy","locality","distance","cancellation"):
   values=[next(r for r in summary if r["model"]==model and r["metric"]==f"{phase}_{metric}")["median"] for phase in ("early","middle","late")];depth.append(f"| {model} | {metric} | {fmt(values[0])} | {fmt(values[1])} | {fmt(values[2])} |")
 global_support={}
 for model in ("vit_b16","deit_s16"):
  by={t["contrast"]:t for t in tests if t["model"]==model};global_support[model]=bool(by["late_minus_early_entropy"]["reject"] and by["late_minus_early_entropy"]["median_difference"]>0 and by["late_minus_early_locality"]["reject"] and by["late_minus_early_locality"]["median_difference"]<0 and by["late_minus_early_distance"]["reject"] and by["late_minus_early_distance"]["median_difference"]>0)
 scientific={"status":"M3_FIDELITY_AND_FROZEN_ATLAS_SUPPORTED","nns_endpoint_equivalence":"SUPPORTED","vit_operator_jacobians":"SUPPORTED","joint_local_to_global":global_support,"atlas_tests":tests,"scope":"frozen stratified token-channel local input-dependence audit"};(ROOT/"scientific_decision.json").write_text(json.dumps(scientific,indent=2)+"\n")
 phase_rows=csvrows("similarity_phase_image_values.csv");phase_summary=[]
 for key in sorted({(r["model_id"],r["phase"],r["group"],r["metric"]) for r in phase_rows}):
  values=[float(r["median"]) for r in phase_rows if (r["model_id"],r["phase"],r["group"],r["metric"])==key and r["median"] not in ("","None")];phase_summary.append({"model":key[0],"phase":key[1],"group":key[2],"metric":key[3],"images":len(values),"median":float(__import__('numpy').median(values)),"ci95":bootstrap_median(values,"similarity|"+"|".join(key),10000)})
 with (ROOT/"similarity_phase_summary.csv").open("w",newline="") as f:
  w=csv.DictWriter(f,fieldnames=list(phase_summary[0]));w.writeheader();w.writerows({**r,"ci95":json.dumps(r["ci95"],separators=(",",":"))} for r in phase_summary)
 similarity_table="\n".join(f"| {r['model']} | {r['phase']} | {r['group']} | {r['metric']} | {r['median']:.4f} | [{r['ci95'][0]:.4f}, {r['ci95'][1]:.4f}] |" for r in phase_summary)
 common_zh=f"""原始 NNS 显式逐层 learning-image 传播与 `x * grad` 在五类兼容网络、float64/float32 各 100 个随机输入上完成 5,000 个逐目标比较。全部通过；最大 relative L2 为 `{fid['max_relative_l2']:.3e}`，最大容差比为 `{fid['max_tolerance_ratio']:.3e}`。11 类 ViT 算子共 88 个方向的解析 JVP、autograd JVP/VJP 和中心有限差分均通过；最大解析-autograd 相对误差 `{op['max_analytic_autograd_jvp_relative_error']:.3e}`，最坏的最佳有限差分相对误差 `{op['max_best_finite_difference_relative_error']:.3e}`。\n\n双模型共享 100 张冻结图像；每模型每图审计 12×16×32=6,144 个 post-block token-channel 标量，共 `{validation['targets']:,}` 个目标记录。该分层审计覆盖 ViT-B/16 全部 post-block token-channel 的 0.338% 和 DeiT-S 的 0.677%。zero-gradient 共 `{validation['zero_gradients']:,}` 个，其派生比率严格记录为 NA。冻结 float32 有限差分检查中 57,600 项有 36 项未过门槛，并保留为初始 FAIL 证据。预先发布的恢复规则选中全部 10 个相关 task；其 float64 多步长复核通过，数值状态为 `PASS_FLOAT64_RECOVERY_WITH_RETAINED_FLOAT32_FAILURE`。"""
 proposition_zh="""定义 `L(u;x)=J_(u,x)(x) diag(x)`。若 `v=f(u_1,...,u_r)`，链式法则给出 `L(v;x)=sum_a J_(f,u_a)(x)L(u_a;x)=J_(v,x)(x)diag(x)`；对标量 `s` 即为 `E_s(x)=x*grad_x s(x)`。数值复现独立实现 Linear、Conv、ReLU、MaxPool 和 residual add 的递推。命题以模型实际接收的 normalized input 为坐标；bias 不作为图像坐标；ReLU 零点使用框架次梯度；MaxPool 使用实际 winner；等价对象是局部输入依赖图而非函数值 completeness；CLS、position embedding 和模型 bias 不分配图像输入贡献；ViT 平滑算子使用当前点真实 Jacobian。"""
 common_en=f"""Explicit layerwise NNS learning-image propagation and `x * grad` were compared on five compatible network families using 100 random inputs per float64/float32 condition, yielding 5,000 target-level comparisons. All passed; the maximum relative L2 error was `{fid['max_relative_l2']:.3e}` and the maximum tolerance ratio was `{fid['max_tolerance_ratio']:.3e}`. Analytic JVP, autograd JVP/VJP, and central finite differences passed for 88 directions across 11 ViT operators. The maximum analytic-autograd relative error was `{op['max_analytic_autograd_jvp_relative_error']:.3e}`; the worst best-step finite-difference relative error was `{op['max_best_finite_difference_relative_error']:.3e}`.\n\nThe two models shared 100 frozen images. Each model-image audited 12×16×32=6,144 post-block token-channel scalars, for `{validation['targets']:,}` target records. The stratified audit covers 0.338% of all post-block token-channel units in ViT-B/16 and 0.677% in DeiT-S. The `{validation['zero_gradients']:,}` zero-gradient records propagate NA to undefined ratios. Of 57,600 frozen float32 finite-difference conditions, 36 missed the threshold and remain as the initial FAIL evidence. The published recovery rule selected all 10 affected tasks; their float64 multi-step review passed, yielding `PASS_FLOAT64_RECOVERY_WITH_RETAINED_FLOAT32_FAILURE`."""
 proposition_en="""Define `L(u;x)=J_(u,x)(x) diag(x)`. For `v=f(u_1,...,u_r)`, the chain rule gives `L(v;x)=sum_a J_(f,u_a)(x)L(u_a;x)=J_(v,x)(x)diag(x)`; for scalar `s`, this is `E_s(x)=x*grad_x s(x)`. The numerical reproduction independently implements this recursion for Linear, Conv, ReLU, MaxPool, and residual addition. Coordinates are the normalized inputs received by the model; biases are not image coordinates; ReLU uses the framework subgradient at zero; MaxPool uses the realized winner; equivalence concerns local input dependence rather than function-value completeness; CLS, position embeddings, and model biases receive no separate image-coordinate allocation; and smooth ViT operators use their true Jacobian at the observed point."""
 zh=f"""# Endpoint M3：NNS 忠实性与分层 token-channel 图谱\n\n## 方法与执行状态\n\n{common_zh}\n\n## 等价命题与条件\n\n{proposition_zh}\n\n## 图谱结果\n\n| 模型 | 指标 | Early | Middle | Late |\n|---|---|---:|---:|---:|\n{chr(10).join(depth)}\n\n| 模型 | 冻结比较 | 中位图像级差值 | 正/负/平 | Holm p | 判定 |\n|---|---|---:|---:|---:|---|\n{test_table}\n\n“由局部趋向全局”的联合判据要求 entropy 上升、locality 下降和 distance 上升同时通过 Holm：ViT-B/16 为 `{'SUPPORTED' if global_support['vit_b16'] else 'NOT_SUPPORTED'}`，DeiT-S 为 `{'SUPPORTED' if global_support['deit_s16'] else 'NOT_SUPPORTED'}`。该判定描述冻结抽样 token-channel 的局部一阶输入依赖。\n\n## 神经元图相似性\n\n| 模型 | 深度 | 配对组 | 指标 | 中位数 | 95% image-bootstrap CI |\n|---|---|---|---|---:|---:|\n{similarity_table}\n\nAbsolute-distribution cosine 在 same-token/different-channel 组始终较高；different-token 组随深度增加。Signed cosine 大多接近零。以上为冻结配对的描述性结果。\n\n## 证据边界\n\nEndpoint 在此处表示 normalized image coordinates 上的局部 Jacobian learning image。跨模型 channel ID 不构成对应神经元。M3 评估分层 atlas；有限替换行为仍由 M1/M2 标定。\n"""
 en=f"""# Endpoint M3: NNS fidelity and stratified token-channel atlas\n\n## Methods and execution status\n\n{common_en}\n\n## Equivalence proposition and conditions\n\n{proposition_en}\n\n## Atlas results\n\n| Model | Metric | Early | Middle | Late |\n|---|---|---:|---:|---:|\n{chr(10).join(depth)}\n\n| Model | Frozen contrast | Median image-level difference | Pos/neg/tie | Holm p | Decision |\n|---|---|---:|---:|---:|---|\n{test_table}\n\nThe joint local-to-global criterion requires a Holm-supported entropy increase, locality decrease, and distance increase. It is `{'SUPPORTED' if global_support['vit_b16'] else 'NOT_SUPPORTED'}` for ViT-B/16 and `{'SUPPORTED' if global_support['deit_s16'] else 'NOT_SUPPORTED'}` for DeiT-S. This decision describes local first-order input dependence for the frozen token-channel sample.\n\n## Neuron-map similarity\n\n| Model | Depth | Pair group | Metric | Median | 95% image-bootstrap CI |\n|---|---|---|---|---:|---:|\n{similarity_table}\n\nAbsolute-distribution cosine remains high for same-token/different-channel pairs and increases with depth for different-token pairs. Signed cosine is generally near zero. These are descriptive results for the frozen pairs.\n\n## Evidence boundary\n\nEndpoint denotes a local Jacobian learning image over normalized image coordinates. Channel IDs are not matched neurons across models. M3 evaluates the stratified atlas; finite-replacement behavior remains calibrated by M1/M2.\n"""
 (REPO/"docs/endpoint_m3_results_20260919.md").write_text(zh);(PAPER/"zh/endpoint_m3_supplement.md").write_text(zh);(PAPER/"en/endpoint_m3_supplement.md").write_text(en)
 evidence=f"""# Endpoint M3 evidence matrix\n\n| Claim | Evidence | Status |\n|---|---|---|\n| Original NNS equivalence | `m3a_fidelity.json`: 5 graph families, 2 dtypes, 100 inputs each, 5,000 target comparisons | PASS |\n| ViT operator derivatives | `m3a_operator_validation.json`: 11 operators, 88 directions, analytic JVP/autograd/VJP/FD | PASS |\n| Frozen stratified atlas | `target_registry.json`, `cohort.json`, `task_validation.json`: 200 tasks and {validation['targets']:,} targets | PASS |\n| Numerical recovery | `initial_numeric_validation_failure.json` plus `m3b_float64_recovery.json`: 36 float32 failures retained and all 10 selected tasks pass float64 review | PASS_WITH_RETAINED_FAILURE |\n| M3 atlas decisions | `image_values.csv`, `atlas_summary.csv`, `atlas_tests.json`; image unit and per-model Holm families | PASS |\n| Unit-map similarity | `similarity_image_values.csv`, `similarity_phase_image_values.csv`, `similarity_summary.csv`; 256 frozen pairs/layer/group | DESCRIPTIVE |\n| Full-resolution examples | `full_map_manifest.json`; 120 pre-frozen raw float32 maps | PASS |\n| Scope | 6,144 sampled token-channel units/model/image; no exhaustive-neuron or finite-intervention claim | BOUNDARY |\n""";(PAPER/"notes/endpoint_m3_evidence_matrix.md").write_text(evidence)
 print(json.dumps({"status":"PASS","scientific_status":scientific["status"],"joint_local_to_global":global_support}))
if __name__=="__main__":main()
